const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64Pdf = binaryBuffer.toString('base64');
const webhookData = $('Webhook').first().json;
const fileName = webhookData.body.fileName;

const prompt = "Extract the following invoice data from the provided PDF invoice.

Mandatory fields:
- invoiceId (Use the exact ID found, e.g. INV-2026-X. Do not invent one.)
- invoiceNumber (e.g. RE-2026-X)
- supplierName
- invoiceDate (Format YYYY-MM-DD)
- amountGross (Float number)
- currency (3-letter uppercase ISO code, e.g., EUR)
- iban (remove all spaces, e.g. DE1234...)
- billingAddress (complete billing address of the recipient)

Optional fields:
- dueDate (Format YYYY-MM-DD)
- amountNet (Float number)
- supplierEmail
- invoiceItems (array of objects with description, quantity, unitPrice, totalPrice)

For each mandatory field, provide a confidence score between 0.0 and 1.0 based on how sure you are. Put these scores in a 'confidence' object with keys matching the field names.

Output MUST be a single, valid JSON object matching this schema:
{
  "invoiceId": "...",
  "invoiceNumber": "...",
  "supplierName": "...",
  "supplierEmail": "...",
  "invoiceDate": "YYYY-MM-DD",
  "dueDate": "YYYY-MM-DD",
  "amountGross": 123.45,
  "amountNet": 100.00,
  "currency": "EUR",
  "iban": "...",
  "billingAddress": "...",
  "invoiceItems": [
    {"description": "...", "quantity": 1.0, "unitPrice": 123.45, "totalPrice": 123.45}
  ],
  "confidence": {
    "invoiceId": 1.0,
    "invoiceNumber": 1.0,
    "supplierName": 1.0,
    "invoiceDate": 1.0,
    "amountGross": 1.0,
    "currency": 1.0,
    "iban": 1.0,
    "billingAddress": 1.0
  }
}";

const requestBody = {
  contents: [
    {
      parts: [
        {
          inlineData: {
            mimeType: "application/pdf",
            data: base64Pdf
          }
        },
        {
          text: prompt
        }
      ]
    }
  ],
  generationConfig: {
    responseMimeType: "application/json"
  }
};

return [{ json: { requestBody, fileName } }];

const response = $input.first().json;
const responseText = response.candidates[0].content.parts[0].text;
let parsedData;

try {
  parsedData = JSON.parse(responseText);
} catch (e) {
  parsedData = {
    error: "Failed to parse model response as JSON",
    rawResponse: responseText
  };
}

const webhookData = $('Webhook').first().json;
parsedData.sourceFile = webhookData.body.fileName;
parsedData.extractionEngine = "n8n+gemini-2.5-flash";

return [{ json: parsedData }];
